select p.id, p.item_type, p.title, p.summary, p.content, p.parent_id, p.category_id, p.cover_url, p.file_url, p.thumbnail_url, p.resource_type, p.processing_status, p.processing_message, p.related_exam_id, p.related_paper_id, p.user_id, u.user_name, u.nick_name as user_nick_name, p.answer_content, p.status, p.sort_order, p.duration_minutes, p.credit, p.score, p.start_time, p.finish_time, p.create_by, p.create_time, p.update_by, p.update_time, p.remark, c.title as course_title, c.duration_minutes as target_duration_minutes, case when c.duration_minutes is null or c.duration_minutes <= 0 then case when p.status = 'completed' then 100 else 0 end else least(round(coalesce(p.duration_minutes, 0) * 100 / c.duration_minutes, 1), 100) end as progress_percent, 0 as learner_count, 0 as completed_count, 0 as resource_count from exam_training_item p left join exam_training_item c on c.id = p.parent_id and c.item_type = 'course' left join sys_user u on u.user_id = p.user_id
